<div class="flex flex-col gap-6">
    <div class="text-center"><flux:heading size="xl">Reset password</flux:heading><flux:text>Choose a new password for your account.</flux:text></div>
    <form wire:submit="resetPassword" class="flex flex-col gap-5"><flux:input wire:model="email" label="Email address" type="email" /><flux:input wire:model="password" label="New password" type="password" viewable /><flux:input wire:model="passwordConfirmation" label="Confirm password" type="password" viewable /><flux:button type="submit" variant="primary" class="w-full">Reset password</flux:button></form>
</div>